sys_script_client.script:
function onSubmit() {
   //getting data from the form 
   var end = g_form.getValue('end_date');
   var start = g_form.getValue('start_date');

   //checking the fields must not be empty 
   if(end && start){
	//actual comparision as end cn't be earlier than start 
	if(end < start ){
		//show error message and prevent form submission
		g_form.addErrorMessage('The End date can not be earlier than start date ');
		return false;
	}
   }
}
